pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new C(1000, "Test", "TST");
        // deployer is address(this) which is the owner
        // transfer ownership to a fuzzable address so that owned() can be called by different callers
        // but the invariant checks that owner never changes after constructor
    }

    function testFuzz_property(address newOwner, uint256 burnAmount) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != deployer);

        // Burn some tokens as deployer first, then transfer ownership
        vm.prank(deployer);
        if (burnAmount > c.totalSupply()) {
            return; // skip invalid inputs, property still holds
        }
        vm.prank(deployer);
        try c.burn(burnAmount) {} catch {}

        // Transfer ownership to newOwner
        vm.prank(deployer);
        c.owned();
        // Then newOwner calls owned() to trigger the bug if present
        vm.prank(newOwner);
        try c.owned() {} catch {}

        // After all calls, owner must still be deployer (the original msg.sender of constructor)
        assertTrue(c.owner() == deployer);
    }
}

