import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address attacker, uint256 burnAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        // Only original deployer (this contract) is initial owner
        // attacker tries to become owner via owned()
        vm.prank(attacker);
        c.owned();
        // Give attacker enough balance for burn
        vm.prank(address(c)); // cheat: we need to give attacker some tokens for burn, but mintToken onlyOwner
        // Instead, we transfer tokens to attacker from deployer balance
        // Deployer has totalSupply, so we can transfer
        vm.prank(address(this));
        c.transfer(attacker, 1);
        vm.assume(c.balanceOf(attacker) >= burnAmount);
        vm.prank(attacker);
        c.burn(burnAmount);
        address currentOwner = c.owner();
        assertTrue(currentOwner == address(this) || currentOwner == attacker);
        // The invariant: owner never changes if the caller is not the original owner in the correct contract.
        // But the bug allows attacker to become owner, so after attacker calls owned() and then any function,
        // the owner in buggy version becomes attacker, while in correct version it remains this.
        // The above assertion will pass in correct version (owner == this) but fail in buggy when fuzzer finds attacker != this.
    }
}

