contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount, address owner) public {
        vm.assume(initialSupply > 0 && burnAmount > 0 && burnAmount <= initialSupply);
        vm.assume(owner != address(0));
        // Deploy a fresh contract with the fuzzed initial supply and owner
        vm.startPrank(owner);
        C freshC = C(0x0000000000000000000000000000000000000000); // placeholder
        // Deploy with fuzzed owner as msg.sender
        vm.stopPrank();
        vm.prank(owner);
        freshC = new C(initialSupply, "TEST", "TST");
        // Transfer some balance to owner from the default deployer? No, owner is owner.
        // Mint additional to owner if needed? No, just burn what we have.
        // Need to ensure owner has enough balance. After constructor, owner has totalSupply.
        // But the constructor sets owner = payable(msg.sender), so owner is indeed the deployer.
        vm.prank(owner);
        freshC.burn(burnAmount);
        // Now compute sum of all balanceOf. Since we only have one account with balance (owner),
        // and frozenAccount mapping is empty, we can iterate over all accounts? Not possible on-chain.
        // So we need a different invariant that doesn't require loop over all addresses.
        // Re-read requirement: must be a general rule that reference satisfies and bug breaks.
        // The bug is that totalSupply is not decreased after burn. So after burn, totalSupply should be initialSupply - burnAmount.
        // Reference: totalSupply() == initialSupply * 10**uint256(decimals) - burnAmount
        // Bug: totalSupply() == initialSupply * 10**uint256(decimals)
        uint256 expectedTotalSupply = initialSupply * 10 ** uint256(0) - burnAmount; // decimals = 0, so 10^0 = 1
        assertTrue(freshC.totalSupply() == expectedTotalSupply);
    }
}

